INSERT INTO tb_product (name, description, price, img_url) VALUES ('Apple iPhone 15 Pro Max', 'Smartphone com chip A17 Pro, câmera de 48 MP com zoom óptico 5x, tela Super Retina XDR de 6,7" e titânio grau aeroespacial.', 8999.99, 'https://i.imgur.com/pfIxvBk.jpeg');
INSERT INTO tb_product (name, description, price, img_url) VALUES ('Samsung Galaxy S24 Ultra', 'Smartphone com câmera de 200 MP, S Pen integrada, processador Snapdragon 8 Gen 3 e tela Dynamic AMOLED de 6,8".', 7499.99, 'https://i.imgur.com/pfIxvBk.jpeg');
INSERT INTO tb_product (name, description, price, img_url) VALUES ('Sony WH-1000XM5', 'Fone de ouvido over-ear com cancelamento de ruído líder do setor, até 30 horas de bateria e áudio Hi-Res.', 1799.99, 'https://i.imgur.com/OvmGSzL.jpeg');
INSERT INTO tb_product (name, description, price, img_url) VALUES ('Apple AirPods Pro (2ª geração)', 'Fone in-ear com cancelamento ativo de ruído, áudio espacial personalizado e chip H2 para som imersivo.', 1699.99, 'https://i.imgur.com/OvmGSzL.jpeg');
INSERT INTO tb_product (name, description, price, img_url) VALUES ('Samsung Smart TV QLED 55" 4K', 'TV 4K com tecnologia Quantum Dot, painel 144Hz, compatível com Amazon Alexa e Google Assistente.', 3499.99, 'https://i.imgur.com/OvmGSzL.jpeg');
INSERT INTO tb_product (name, description, price, img_url) VALUES ('Amazon Echo Dot (5ª geração)', 'Smart speaker compacto com Alexa, som melhorado e hub de casa inteligente integrado.', 349.99, 'https://i.imgur.com/pfIxvBk.jpeg');
INSERT INTO tb_product (name, description, price, img_url) VALUES ('Logitech MX Master 3S', 'Mouse sem fio premium com sensor de 8000 DPI, scroll MagSpeed eletromagnético e conexão multi-dispositivo.', 499.99, 'https://i.imgur.com/xNQ2ttR.jpeg');
INSERT INTO tb_product (name, description, price, img_url) VALUES ('Razer DeathAdder V3 HyperSpeed', 'Mouse gamer sem fio ultra-leve de 63g com sensor Focus Pro 30K e switches ópticos Razer Gen-3.', 399.99, 'https://i.imgur.com/xNQ2ttR.jpeg');
INSERT INTO tb_product (name, description, price, img_url) VALUES ('Keychron Q1 Pro', 'Teclado mecânico 75% sem fio com switches Gateron G Pro Red, construção em alumínio anodizado e RGB.', 749.99, 'https://i.imgur.com/Hs9QmKk.jpeg');
INSERT INTO tb_product (name, description, price, img_url) VALUES ('LG UltraGear 27GP850-B', 'Monitor gamer 27" QHD (2560x1440) com painel Nano IPS, 180Hz, 1ms GTG e NVIDIA G-SYNC Compatible.', 1999.99, 'https://i.imgur.com/OvmGSzL.jpeg');
INSERT INTO tb_product (name, description, price, img_url) VALUES ('The Pragmatic Programmer', 'Clássico da engenharia de software de David Thomas e Andrew Hunt — guia essencial para tornar-se um desenvolvedor melhor.', 159.99, 'https://i.imgur.com/wFQdLgD.jpeg');
INSERT INTO tb_product (name, description, price, img_url) VALUES ('Clean Code', 'Robert C. Martin apresenta princípios, padrões e práticas de escrita de código limpo e de fácil manutenção.', 129.99, 'https://i.imgur.com/wFQdLgD.jpeg');
INSERT INTO tb_product (name, description, price, img_url) VALUES ('Design Patterns: Elements of Reusable Object-Oriented Software', 'O livro da Gang of Four que definiu os 23 padrões de projeto fundamentais da orientação a objetos.', 199.99, 'https://i.imgur.com/wFQdLgD.jpeg');
INSERT INTO tb_product (name, description, price, img_url) VALUES ('Harry Potter e a Pedra Filosofal', 'O primeiro livro da saga mágica de J.K. Rowling que apresenta o bruxo Harry Potter ao mundo.', 59.99, 'https://i.imgur.com/wFQdLgD.jpeg');
INSERT INTO tb_product (name, description, price, img_url) VALUES ('O Senhor dos Anéis: A Sociedade do Anel', 'A épica fantasia de J.R.R. Tolkien que deu origem ao gênero de fantasia moderna.', 79.99, 'https://i.imgur.com/wFQdLgD.jpeg');
INSERT INTO tb_product (name, description, price, img_url) VALUES ('Spring Boot em Ação', 'Guia completo para desenvolvimento de aplicações Java modernas com Spring Boot e o ecossistema Spring.', 119.99, 'https://i.imgur.com/wFQdLgD.jpeg');
INSERT INTO tb_product (name, description, price, img_url) VALUES ('Apple MacBook Pro 14" M3 Pro', 'Notebook profissional com chip M3 Pro, tela Liquid Retina XDR de 14,2", 18GB de RAM unificada e SSD de 512GB.', 14999.99, 'https://i.imgur.com/pOfTJ83.png');
INSERT INTO tb_product (name, description, price, img_url) VALUES ('Dell XPS 15 (9530)', 'Notebook premium com Intel Core i7-13700H, NVIDIA RTX 4060, tela OLED 3,5K TouchScreen e 16GB DDR5.', 9999.99, 'https://i.imgur.com/pOfTJ83.png');
INSERT INTO tb_product (name, description, price, img_url) VALUES ('ASUS ROG Strix G16 (2024)', 'Notebook gamer com AMD Ryzen 9 8945HX, NVIDIA RTX 4070, tela FHD 240Hz e 16GB DDR5.', 8499.99, 'https://i.imgur.com/pOfTJ83.png');
INSERT INTO tb_product (name, description, price, img_url) VALUES ('Lenovo ThinkPad X1 Carbon Gen 12', 'Notebook corporativo ultrafino com Intel Core Ultra 7, tela 2,8K OLED Touch, 32GB LPDDR5 e 1TB SSD.', 11499.99, 'https://i.imgur.com/pOfTJ83.png');
INSERT INTO tb_product (name, description, price, img_url) VALUES ('HP Spectre x360 14"', 'Notebook conversível 2-em-1 com Intel Core Ultra 5, tela OLED 2,8K táctil, 16GB RAM e caneta HP incluída.', 7299.99, 'https://i.imgur.com/pOfTJ83.png');
INSERT INTO tb_product (name, description, price, img_url) VALUES ('PlayStation 5 DualSense', 'Controle sem fio com feedback háptico, gatilhos adaptáveis e microfone embutido para o PS5.', 499.99, 'https://i.imgur.com/KpDPKLh.jpeg');
INSERT INTO tb_product (name, description, price, img_url) VALUES ('Xbox Series X Controller', 'Controle sem fio com textura híbrida, botão de compartilhamento e compatível com PC, Xbox e dispositivos móveis.', 449.99, 'https://i.imgur.com/KpDPKLh.jpeg');
INSERT INTO tb_product (name, description, price, img_url) VALUES ('Nintendo Switch Pro Controller', 'Controle premium para Nintendo Switch com giroscópio, vibração HD e durabilidade de bateria de 40h.', 399.99, 'https://i.imgur.com/KpDPKLh.jpeg');
INSERT INTO tb_product (name, description, price, img_url) VALUES ('The Legend of Zelda: Tears of the Kingdom', 'Aventura épica em mundo aberto para Nintendo Switch com mecânicas revolucionárias de construção e exploração.', 299.99, 'https://i.imgur.com/KpDPKLh.jpeg');
INSERT INTO tb_product (name, description, price, img_url) VALUES ('Elden Ring', 'RPG de ação em mundo aberto desenvolvido pela FromSoftware em parceria com George R.R. Martin. Disponível para PS5, Xbox e PC.', 199.99, 'https://i.imgur.com/KpDPKLh.jpeg');
INSERT INTO tb_product (name, description, price, img_url) VALUES ('Red Dead Redemption 2', 'Épico faroeste de mundo aberto da Rockstar Games com gráficos fotorrealistas e narrativa cinematográfica.', 149.99, 'https://i.imgur.com/KpDPKLh.jpeg');
INSERT INTO tb_product (name, description, price, img_url) VALUES ('Nike Air Force 1 ''07', 'Tênis clássico com cabedal em couro e sola de borracha durável. Ícone do streetwear desde 1982.', 699.99, 'https://i.imgur.com/MgkBS8G.jpeg');
INSERT INTO tb_product (name, description, price, img_url) VALUES ('Adidas Ultraboost 22', 'Tênis de corrida com amortecimento Boost, cabedal Primeknit+ e sistema de retorno de energia incomparável.', 799.99, 'https://i.imgur.com/MgkBS8G.jpeg');
INSERT INTO tb_product (name, description, price, img_url) VALUES ('Levi''s 501 Original Jeans', 'Calça jeans icônica com corte reto e botões frontais. Algodão 100% e caimento atemporal.', 349.99, 'https://i.imgur.com/MgkBS8G.jpeg');
INSERT INTO tb_product (name, description, price, img_url) VALUES ('The North Face ThermoBall Eco Jacket', 'Jaqueta leve com isolamento sintético ThermoBall reutilizável (material reciclado), compactável e impermeável.', 999.99, 'https://i.imgur.com/MgkBS8G.jpeg');
INSERT INTO tb_product (name, description, price, img_url) VALUES ('Under Armour HeatGear Compression T-Shirt', 'Camiseta de compressão com tecnologia HeatGear que mantém o corpo fresco e seco durante treinos intensos.', 189.99, 'https://i.imgur.com/MgkBS8G.jpeg');
INSERT INTO tb_product (name, description, price, img_url) VALUES ('Puma RS-X3 Puzzle', 'Tênis casual chunkystyle com cabedal em mesh e couro sintético, sola volumosa e detalhes coloridos.', 549.99, 'https://i.imgur.com/MgkBS8G.jpeg');
